        const gg = g.createLinearGradient(0, y0, 0, y0 + l);
        gg.addColorStop(0, farbe([170, 184, 205], F.ls, 0)); gg.addColorStop(0.4, farbe([170, 184, 205], F.ls, 0.28)); gg.addColorStop(1, farbe([170, 184, 205], F.ls, 0));
